/** True when a live certificate + key really exist here for this exact name. */
async function certExists(conn: Client, domain: string): Promise<boolean> {
  if (!DOMAIN_RE.test(domain)) return false;
  return shOk(conn, `test -s /etc/letsencrypt/live/${domain}/fullchain.pem && test -s /etc/letsencrypt/live/${domain}/privkey.pem`);
