/** Does this hostname already resolve to the NEW server? HTTP-01 requires it. */
async function resolvesHere(conn: Client, domain: string, ip: string): Promise<boolean> {
  if (!DOMAIN_RE.test(domain) || !IPV4_RE.test(ip)) return false;
  const r = await sh(conn, `getent ahostsv4 ${domain} 2>/dev/null | awk '{print $1}' | sort -u | head -n 8`);
