/**
 * Persist the WHOIS-privacy preference. name.com's privacy is a paid add-on
 * set at registration rather than a free live toggle, so this is persisted-
 * only: we record intent and surface a note. Ownership-checked.
 */
export async function setWhoisPrivacy(
  domainId: string,
  enabled: boolean
): Promise<{ error?: string; whoisPrivacy?: boolean; note?: string }> {
  const { user, domain } = await ownedDomain(domainId);

  await db.domain.update({ where: { id: domainId }, data: { whoisPrivacy: enabled } });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "domain.whois_privacy",
      detail: `${domainId} -> ${enabled ? "on" : "off"}`,
    },
  });
  revalidatePath(`/dashboard/domains/${domainId}`);
  return {
    whoisPrivacy: enabled,
    note: `Preference saved (${enabled ? "on" : "off"}). WHOIS privacy at ${domain.registrar} is provisioned at registration — contact support to change it on a live domain.`,
  };
}

